sp_widget.script:
(function() {
  data.validations = [];
  data.allValid = true;
  data.applicationId = $sp.getParameter("app_id") || "";

  try {
    if (!data.applicationId) return;

    // Check required document types
    var requiredDocs = ["architecture", "security", "compliance"];
    var attachGr = new GlideRecord("sys_attachment");
    attachGr.addQuery("table_name", "x_1433041_identi_0_application");
    attachGr.addQuery("table_sys_id", data.applicationId);
    attachGr.setLimit(50);
    attachGr.query();

    var uploadedTypes = [];
    while (attachGr.next()) {
      uploadedTypes.push(attachGr.getValue("file_name"));
    }

    var docLabels = {
      architecture: "Architecture Diagram",
      security: "Security Assessment",
      compliance: "Compliance Certificate"
    };

    for (var i = 0; i < requiredDocs.length; i++) {
      var docType = requiredDocs[i];
      var found = false;
      for (var j = 0; j < uploadedTypes.length; j++) {
        if (uploadedTypes[j].toLowerCase().indexOf(docType) !== -1) {
          found = true;
          break;
        }
      }
      data.validations.push({
        type: docType,
        label: docLabels[docType],
        valid: found,
        message: found ? "Document uploaded" : "Required document missing"
      });
      if (!found) data.allValid = false;
    }
  } catch (e) {
    gs.error("IBAR Document Validation widget error: " + e.message);
  }
})();
